/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  random,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Roboto');

const { fontFamily: robotoFontFamily } = loadFont();



export type MoneyExplosionProps = Record<string, any>;

const MoneyExplosion: React.FC<MoneyExplosionProps> = ({
  backgroundColor = "#f3f0eb", // Default to a paper-like off-white
  transparentBackground = false,
  durationInSeconds = 5,
  mainSymbolColor = "#2d2d2d", // Charcoal pencil
  particleColor = "#1a1a1a",   // Dark Ink
  particleCount = 40,
  explosionProgress = 0.5,
  bubbleText = "how can we definitely know that the gospel is true?",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // 1. Stop Motion Engine
  // We reduce the frame rate for calculations to simulate 6fps drawing style (on a 30fps timeline)
  const step = 5; 
  const steppedFrame = Math.floor(frame / step) * step;

  // Helper for "boiling" lines (jittering points)
  const getJitter = (seed: number, amp: number = 3) => {
    return (random(seed + steppedFrame) - 0.5) * amp;
  };

  // 2. Character Sketch Generation (Sitting Figure)
  // We generate a few "strokes" for a sketchy pencil look
  const characterStrokes = useMemo(() => {
    // Defines a rough sitting pose relative to center
    // Head, Back, Legs, Arms
    return [
      // Head (Circle-ish)
      { type: "circle", cx: 0, cy: -60, r: 25 },
      // Spine/Back (Curved)
      { type: "path", d: "M 0,-35 Q -10,0 -10,60" },
      // Legs (Folded)
      { type: "path", d: "M -10,60 Q 30,50 35,80" }, // Thigh
      { type: "path", d: "M 35,80 Q 35,110 5,110" }, // Shin
      // Arms (Resting on knees)
      { type: "path", d: "M -5,-20 Q 20,20 30,70" },
    ];
  }, []);

  // 3. Scribbled Thoughts (Particles)
  // These swirl around the head
  const thoughtParticles = useMemo(() => {
    return new Array(particleCount).fill(0).map((_, i) => {
      const seed = i * 777;
      // Random initial position in a cloud around the head
      const angle = random(seed) * Math.PI * 2;
      const radius = 60 + random(seed + 1) * 100; // Distance from head
      const size = 10 + random(seed + 2) * 30;
      const speed = 0.2 + random(seed + 3) * 0.5;
      
      // Generate a random scribble path
      const points = 5 + Math.floor(random(seed + 4) * 5);
      let d = `M 0 0`;
      for (let j = 0; j < points; j++) {
        const x = (random(seed + j * 10) - 0.5) * size;
        const y = (random(seed + j * 11) - 0.5) * size;
        d += ` L ${x} ${y}`;
      }
      
      return { angle, radius, size, speed, d, seed };
    });
  }, [particleCount]);

  // -- Animation Logic --

  // Mood lighting / vignette intensity based on progress
  // As explosionProgress increases, the thoughts get darker/more intense
  const totalFrames = durationInSeconds * fps;
  
  // The thoughts emerge based on explosionProgress param
  // We map the slider (0.2 - 0.8) to a time in the video where intensity peaks
  const peakFrame = totalFrames * explosionProgress;
  
  const intensity = interpolate(
    frame,
    [0, peakFrame, totalFrames],
    [0, 1, 0.8], // Builds up then settles slightly
    { easing: Easing.bezier(0.42, 0, 0.58, 1) }
  );

  // Canvas-relative sizes for bubble quote
  const scale = Math.min(width, height) / 1080;
  const bubbleWidth = 480 * scale;
  const bubbleHeight = 150 * scale;
  const r = 16 * scale;
  const tailW = 15 * scale;
  const textStartFrame = 15;
  const typingSpeed = 1.2; // frames per character

  const bubblePath = useMemo(() => {
    const x1 = -bubbleWidth / 2;
    const x2 = bubbleWidth / 2;
    const y1 = -90 - 20 * scale - bubbleHeight;
    const y2 = -90 - 20 * scale;
    const tailTipX = 0;
    const tailTipY = -90;
    
    return `
      M ${x1 + r} ${y1}
      L ${x2 - r} ${y1}
      Q ${x2} ${y1} ${x2} ${y1 + r}
      L ${x2} ${y2 - r}
      Q ${x2} ${y2} ${x2 - r} ${y2}
      L ${tailW} ${y2}
      L ${tailTipX} ${tailTipY}
      L ${-tailW} ${y2}
      L ${x1 + r} ${y2}
      Q ${x1} ${y2} ${x1} ${y2 - r}
      L ${x1} ${y1 + r}
      Q ${x1} ${y1} ${x1 + r} ${y1}
      Z
    `;
  }, [bubbleWidth, bubbleHeight, r, tailW, scale]);

  const padding = 20 * scale;
  const foX = -bubbleWidth / 2 + padding;
  const foY = -90 - 20 * scale - bubbleHeight + padding;
  const foWidth = bubbleWidth - padding * 2;
  const foHeight = bubbleHeight - padding * 2;

  // Bubble appearance animation
  const bubbleEntranceProgress = interpolate(
    frame,
    [5, 15],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.back(1.1),
    }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: transparentBackground ? "transparent" : backgroundColor,
        fontFamily: robotoFontFamily,
        overflow: "hidden",
      }}
    >
      {/* Paper Texture Filter Definition */}
      <svg style={{ position: "absolute", width: 0, height: 0 }}>
        <filter id="paper-noise">
          <feTurbulence
            type="fractalNoise"
            baseFrequency="0.8"
            numOctaves="3"
            stitchTiles="stitch"
          />
          <feColorMatrix type="saturate" values="0" />
          <feComponentTransfer>
            <feFuncA type="linear" slope="0.1" />
          </feComponentTransfer>
        </filter>
        <filter id="pencil-texture">
          <feTurbulence
            type="fractalNoise"
            baseFrequency="0.05"
            numOctaves="2"
            result="noise"
          />
          <feDisplacementMap
            in="SourceGraphic"
            in2="noise"
            scale="3"
          />
        </filter>
      </svg>

      {/* Paper Texture Overlay */}
      {!transparentBackground && (
        <AbsoluteFill
          style={{
            zIndex: 0,
            opacity: 0.6,
            mixBlendMode: "multiply",
            filter: "url(#paper-noise)",
          }}
        />
      )}

      {/* Main Scene Container */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <svg
          width={width}
          height={height}
          viewBox={`${-width / 2} ${-height / 2} ${width} ${height}`}
          style={{ overflow: "visible" }}
        >
          {/* Character Group */}
          <g filter="url(#pencil-texture)">
            {characterStrokes.map((stroke, i) => {
              // Create "Sketchy" effect by drawing the same line multiple times with slight offsets
              const numPasses = 3;
              return (
                <g key={`char-${i}`}>
                  {new Array(numPasses).fill(0).map((_, pIndex) => {
                    const passSeed = i * 100 + pIndex;
                    const jx = getJitter(passSeed, 2);
                    const jy = getJitter(passSeed + 1, 2);
                    
                    if (stroke.type === "circle") {
                      return (
                        <ellipse
                          key={pIndex}
                          cx={(stroke.cx || 0) + jx}
                          cy={(stroke.cy || 0) + jy}
                          rx={(stroke.r || 0) + getJitter(passSeed + 2, 1)}
                          ry={(stroke.r || 0) + getJitter(passSeed + 3, 1)}
                          fill="none"
                          stroke={mainSymbolColor}
                          strokeWidth={2 + random(passSeed) * 1.5}
                          strokeLinecap="round"
                          opacity={0.7}
                        />
                      );
                    } else {
                      return (
                        <path
                          key={pIndex}
                          d={stroke.d}
                          transform={`translate(${jx}, ${jy})`}
                          fill="none"
                          stroke={mainSymbolColor}
                          strokeWidth={2 + random(passSeed) * 1.5}
                          strokeLinecap="round"
                          opacity={0.8}
                        />
                      );
                    }
                  })}
                </g>
              );
            })}
          </g>

          {/* Swirling Thoughts (Particles) */}
          <g filter="url(#pencil-texture)">
            {thoughtParticles.map((p, i) => {
              // Animate position: swirl around center
              const currentAngle = p.angle + (frame * p.speed * 0.02);
              // Radius breathes slightly
              const currentRadius = p.radius + Math.sin(frame * 0.05 + p.seed) * 10;
              
              const x = Math.cos(currentAngle) * currentRadius;
              const y = (Math.sin(currentAngle) * currentRadius) - 60; // Offset to center around head area

              // Fade in/out based on intensity and individuality
              const personalDelay = (p.seed % 20);
              const active = frame > personalDelay;
              if (!active) return null;

              // Scale appearance based on intensity
              const scaleFactor = interpolate(
                intensity, 
                [0, 1], 
                [0, 1.5], 
                { extrapolateRight: "clamp" }
              ) * (0.8 + 0.4 * Math.sin(frame * 0.1 + p.seed));

              const opacity = interpolate(
                intensity,
                [0, 0.2],
                [0, 0.9],
                { extrapolateRight: "clamp" }
              );

              // Jitter position for stop motion feel
              const jx = getJitter(p.seed, 5);
              const jy = getJitter(p.seed + 1, 5);

              return (
                <g 
                    key={`thought-${i}`} 
                    transform={`translate(${x + jx}, ${y + jy}) scale(${scaleFactor}) rotate(${frame * p.speed})`}
                    style={{ opacity }}
                >
                    <path
                        d={p.d}
                        fill="none"
                        stroke={particleColor}
                        strokeWidth={1.5}
                        strokeLinecap="round"
                        strokeLinejoin="round"
                    />
                </g>
              );
            })}
          </g>

          {/* Bubble Quote */}
          {bubbleEntranceProgress > 0 && (
            <g
              transform={`translate(0, -90) scale(${bubbleEntranceProgress}) translate(0, 90)`}
              style={{ opacity: bubbleEntranceProgress }}
            >
              {/* Solid base fill for legibility */}
              <path
                d={bubblePath}
                fill={backgroundColor}
                opacity={0.95}
              />
              
              {/* Hand-drawn sketchy border lines */}
              <g filter="url(#pencil-texture)">
                {new Array(3).fill(0).map((_, pIndex) => {
                  const passSeed = 9999 + pIndex;
                  const jx = getJitter(passSeed, 1.5);
                  const jy = getJitter(passSeed + 1, 1.5);
                  return (
                    <path
                      key={pIndex}
                      d={bubblePath}
                      transform={`translate(${jx}, ${jy})`}
                      fill="none"
                      stroke={mainSymbolColor}
                      strokeWidth={2 + random(passSeed) * 1}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      opacity={0.8}
                    />
                  );
                })}
              </g>

              {/* Text Area */}
              <foreignObject
                x={foX}
                y={foY}
                width={foWidth}
                height={foHeight}
              >
                <div
                  style={{
                    width: "100%",
                    height: "100%",
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    textAlign: "center",
                    fontFamily: robotoFontFamily,
                    fontSize: 26 * scale,
                    color: mainSymbolColor,
                    lineHeight: 1.35,
                    fontWeight: "600",
                  }}
                >
                  <div style={{ display: "inline", maxWidth: "100%" }}>
                    {bubbleText.split("").map((char, index) => {
                      const charProgress = frame - textStartFrame - index * typingSpeed;
                      
                      const opacity = interpolate(
                        charProgress,
                        [0, 6],
                        [0, 1],
                        { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                      );
                      
                      const blurVal = interpolate(
                        charProgress,
                        [0, 10],
                        [16, 0],
                        { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                      );

                      const scaledBlur = blurVal * scale;

                      return (
                        <span
                          key={index}
                          style={{
                            display: "inline",
                            opacity,
                            filter: scaledBlur > 0 ? `blur(${scaledBlur}px)` : "none",
                            transition: "none",
                          }}
                        >
                          {char}
                        </span>
                      );
                    })}
                  </div>
                </div>
              </foreignObject>
            </g>
          )}
        </svg>
      </div>

      {/* Cinematic Vignette for Moody Atmosphere */}
      {!transparentBackground && (
        <AbsoluteFill
          style={{
            background: "radial-gradient(circle at center, transparent 40%, rgba(0,0,0,0.3) 100%)",
            pointerEvents: "none",
          }}
        />
      )}
    </AbsoluteFill>
  );
};

export default MoneyExplosion;